def transform(grid):
    from collections import deque
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for c in row:
            counts[c] = counts.get(c, 0) + 1
    bg = max(counts, key=lambda c: counts[c])
    minority = [c for c in counts if c != bg]
    out = [row[:] for row in grid]
    seen = [[False]*w for _ in range(h)]
    for i in range(h):
        for j in range(w):
