```python
def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for c in row:
            counts[c] = counts.get(c, 0) + 1
    minority = min(counts, key=lambda c: counts[c])
    out = [row[:] for row in grid]

    def cells(r):
        return [c for c in range(w) if grid[r][c] == minority]

    def longest_run(r):
        best = cur = 0
        for c in range(w):
            if grid[r][c] == minority:
                cur += 1
                best = max(best, cur)
            else:
                cur = 0
        return best

    r = 0
    while r < h:
        if cells(r):
            r2 = r
            while r2 < h and cells(r2):
                r2 += 1
            band = range(r, r2)
            right = {rr: cells(rr)[-1] for rr in band}
            maxc = max(right.values())
            best_run = max(longest_run(rr) for rr in band)
            for rr in band:
                at_max = right[rr] == maxc
                has_best = longest_run(rr) == best_run and best_run >= 2
                if at_max or has_best:
                    for c in range(right[rr] + 1, w):
                        if grid[rr][c] != minority:
                            out[rr][c] = 1
            r = r2
        else:
            r += 1
    return out
