def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for c in row:
            counts[c] = counts.get(c, 0) + 1
    minority = min(counts, key=lambda c: counts[c])
    out = [row[:] for row in grid]

    def has_min(r):
        return any(grid[r][c] == minority for c in range(w))

    def runs(r):
        res = []
        c = 0
        while c < w:
            if grid[r][c] == minority:
                s = c
                while c < w and grid[r][c] == minority:
                    c += 1
                res.append((s, c - 1))
            else:
                c += 1
        return res

    r = 0
    while r < h:
        if has_min(r):
            r2 = r
            while r2 < h and has_min(r2):
                r2 += 1
            all_runs = []
            for rr in range(r, r2):
                for s, e in runs(rr):
                    all_runs.append((e - s + 1, e))
            best_len = max(L for L, e in all_runs)
            cstar = max(e for L, e in all_runs if L == best_len)
            for rr in range(r, r2):
                cells = [c for c in range(w) if grid[rr][c] == minority]
                if cstar in cells:
                    start = cells[-1] + 1
                    for c in range(start, w):
                        if grid[rr][c] != minority:
                            out[rr][c] = 1
            r = r2
        else:
            r += 1
    return out
